package resourcemodifiers

import (
	"os"
	"testing"

	"github.com/sirupsen/logrus"
	corev1api "k8s.io/api/core/v1"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/apimachinery/pkg/runtime"
)

func TestHyperCDRGeneratedConsistencyRestoreModifiers(t *testing.T) {
	path := os.Getenv("HYPERCDR_CONSISTENCY_MODIFIER_FIXTURE")
	if path == "" {
		t.Skip("requires the modifier fixture generated by the Agent consistency restore test")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	modifiers, err := GetResourceModifiersFromConfig(&corev1api.ConfigMap{Data: map[string]string{"resource-modifiers.yaml": string(data)}})
	if err != nil {
		t.Fatal(err)
	}
	for _, scenario := range []string{"paused", "other-run", "other-name", "other-namespace", "already-resumed"} {
		t.Run(scenario, func(t *testing.T) {
			object := &unstructured.Unstructured{Object: map[string]any{
				"apiVersion": "apps/v1", "kind": "Deployment",
				"metadata": map[string]any{"name": "database", "namespace": "app", "annotations": map[string]any{"hypercdr.io/consistency-owner": "123", "preserve": "value"}},
				"spec":     map[string]any{"replicas": int64(0)},
			}}
			switch scenario {
			case "other-run":
				object.SetAnnotations(map[string]string{"hypercdr.io/consistency-owner": "456"})
			case "other-name":
				object.SetName("database-copy")
			case "other-namespace":
				object.SetNamespace("other")
			case "already-resumed":
				object.SetAnnotations(map[string]string{"preserve": "value"})
				_ = unstructured.SetNestedField(object.Object, int64(2), "spec", "replicas")
			}
			if errors := modifiers.ApplyResourceModifierRules(object, "deployments.apps", runtime.NewScheme(), logrus.New()); len(errors) != 0 {
				t.Fatal(errors)
			}
			replicas, _, err := unstructured.NestedInt64(object.Object, "spec", "replicas")
			if err != nil {
				t.Fatal(err)
			}
			want := int64(0)
			if scenario == "paused" || scenario == "already-resumed" {
				want = 2
			}
			if replicas != want {
				t.Fatalf("replicas=%d want=%d", replicas, want)
			}
			if scenario == "paused" && (object.GetAnnotations()["hypercdr.io/consistency-owner"] != "" || object.GetAnnotations()["preserve"] != "value") {
				t.Fatal("restore did not clear pause ownership while preserving unrelated annotations")
			}
		})
	}
}
